    "yaml": "type: grid\ncards:\n- type: heading\n  heading: Energy Compass diagnostics\n  heading_style: title\n  icon: mdi:wrench-outline\n- type: markdown\n  title: Energy Compass diagnostics\n  content: '{% set labels = {''CHARGE_PV'':''Charging from PV'',''CHARGE_GRID'':''Charging from grid'',''DISCHARGE_GRID'':''Selling to grid'',''SELF_CONSUME'':''Powering the house'',''HOLD'':''Holding'',''CURTAIL'':''Holding (PV curtailment)'',''BASE'':''Base mode''} %}\n\n    {% set colors = {''CHARGE_PV'':''🟢'',''CHARGE_GRID'':''🔵'',''DISCHARGE_GRID'':''🟠'',''SELF_CONSUME'':''🟣'',''HOLD'':''⚪'',''CURTAIL'':''⚪'',''BASE'':''⚪''} %}\n\n    {% set rt = state_attr(''sensor.energy_compass_deye_runtime'',''runtime'') or {} %}\n\n    {% set plan = ''__EC_PLAN__'' %}\n\n    {% set valid = is_state(''__EC_VALID__'',''on'') and as_timestamp(state_attr(plan,''valid_until''),0) > as_timestamp(now()) %}\n\n    {% set fresh = as_timestamp(rt.get(''original_deadline''),0) > as_timestamp(now()) and as_timestamp(rt.get(''last_confirmation''),0) > 0 %}\n\n    | Parameter | State |\n\n    |:--|:--|\n\n    | Optimizer | {{ states(''__EC_OPTIMIZER__'') }} |\n\n    | Controller | {{ rt.get(''code'',''No data'') }} |\n\n    | Reason | {{ rt.get(''reason'',''—'') }} |\n\n    | Confirmed mode | {{ labels.get(rt.get(''confirmed_mode''),rt.get(''confirmed_mode'',''—'')) }} |\n\n    | Last confirmation | {{ as_local(as_datetime(rt.get(''last_confirmation''))).strftime(''%d.%m %H:%M:%S'') if as_timestamp(rt.get(''last_confirmation''),0) else ''None'' }} |\n\n    | Plan created | {{ as_local(as_datetime(state_attr(plan,''generated_at''))).strftime(''%d.%m %H:%M:%S'') if as_timestamp(state_attr(plan,''generated_at''),0) else ''None'' }} |\n\n    | Controller plan valid until | {{ as_local(as_datetime(rt.get(''original_deadline''))).strftime(''%d.%m %H:%M:%S'') if as_timestamp(rt.get(''original_deadline''),0) else ''None'' }} |\n\n    | Forecast until | {{ as_local(as_datetime(state_attr(''__EC_VALID__'',''coverage_end''))).strftime(''%d.%m %H:%M'') if as_timestamp(state_attr(''__EC_VALID__'',''coverage_end''),0) else ''None'' }} |\n\n    | Active TOU program | {{ rt.get(''active_tou'',''—'') }} |\n\n    | Unconfirmed writes | {{ rt.get(''uncertain'',[])|length }} |\n\n    | Controller session | {{ states(''input_boolean.energy_compass_deye_session'') }} |\n\n    | Restore after the session | {{ states(''input_boolean.energy_compass_deye_restore_pending'') }} |\n\n\n    {% if rt.get(''warning'') %}⚠️ {{ rt.warning }}{% endif %}\n\n\n    {% if state_attr(plan,''reasons'') %}Model notes: {{ state_attr(plan,''reasons'')|join('', '') }}.{% endif %}\n\n\n    The restore flag can be on during an Auto session. On its own it does not mean a fault.'\n- type: entities\n  title: Inverter limits · read-back\n  show_header_toggle: false\n  entities:\n  - type: simple-entity\n    entity: __EC_CHARGE_LIMIT__\n    name: Charge limit\n  - type: simple-entity\n    entity: __EC_DISCHARGE_LIMIT__\n    name: Discharge limit\n  - type: simple-entity\n    entity: __EC_GRID_LIMIT__\n    name: Grid charge limit\n  - type: simple-entity\n    entity: sensor.energy_compass_deye_next_tou\n    name: Next TOU change\n",
